<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../api/client.js'
import {toSavePayload} from '../api/contracts.js'
const props=defineProps(['kind','value','busy']),emit=defineEmits(['save','close'])
const form=ref({name:'',categoryId:'',type:1,sort:0,status:0,sex:'1',price:0.01,flavors:[],setmealDishes:[],...JSON.parse(JSON.stringify(props.value))}),categories=ref([]),dishes=ref([]),selected=ref(''),uploading=ref(false),uploadError=ref('')
onMounted(async()=>{try{if(['dish','setmeal'].includes(props.kind))categories.value=await api('admin','GET','/category/list',undefined,{type:props.kind==='dish'?1:2});if(props.kind==='setmeal')dishes.value=(await api('admin','GET','/dish/page',undefined,{page:1,pageSize:1000})).records||[]}catch{}})
function addDish(){const d=dishes.value.find(d=>String(d.id)===String(selected.value));if(d&&!form.value.setmealDishes.some(x=>x.dishId===d.id))form.value.setmealDishes.push({dishId:d.id,name:d.name,price:d.price,copies:1})}
async function upload(e){const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){uploadError.value='图片不能超过 5MB';return}uploading.value=true;try{const data=new FormData();data.append('file',file);form.value.image=await api('admin','POST','/common/upload',data);uploadError.value=''}catch{}finally{uploading.value=false}}
function submit(){const payload=toSavePayload(props.kind,form.value);if(props.kind==='dish')payload.flavors=(form.value.flavors||[]).map(f=>({...f,value:f.value.startsWith('[')?f.value:JSON.stringify(f.value.replaceAll('，',',').split(',').map(s=>s.trim()).filter(Boolean))}));emit('save',payload)}
</script>
<template><div class="overlay" @click.self="$emit('close')"><form class="modal" @submit.prevent="submit"><div class="section-title"><h2>{{value.id?'编辑':'新增'}}{{{dish:'菜品',setmeal:'套餐',category:'分类',employee:'员工'}[kind]}}</h2><button type="button" @click="$emit('close')">关闭</button></div><label>名称<input v-model="form.name" required maxlength="32"></label><template v-if="kind==='employee'"><label>账号<input v-model="form.username" required></label><label>手机号<input v-model="form.phone" type="tel" pattern="[0-9]{11}" required></label><label>身份证号<input v-model="form.idNumber" required maxlength="18"></label><label>性别<select v-model="form.sex"><option value="1">男</option><option value="0">女</option></select></label></template><template v-if="kind==='category'"><label>类型<select v-model.number="form.type"><option :value="1">菜品分类</option><option :value="2">套餐分类</option></select></label><label>排序<input v-model.number="form.sort" type="number" min="0" required></label></template><template v-if="['dish','setmeal'].includes(kind)"><label>分类<select v-model="form.categoryId" required><option disabled value="">请选择分类</option><option v-for="c in categories" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>售价（元）<input v-model.number="form.price" type="number" min="0.01" step="0.01" required></label><label>图片<input type="file" accept="image/*" @change="upload"><span v-if="uploading">上传中…</span><span>{{uploadError}}</span><img v-if="form.image" :src="form.image" class="preview-image" alt="商品图片"></label><label>描述<textarea v-model="form.description" maxlength="500"></textarea></label></template><template v-if="kind==='dish'"><h3>口味选项</h3><div v-for="(f,i) in form.flavors" :key="i" class="flavor-row"><input v-model="f.name" placeholder="口味名称" required aria-label="口味名称"><input v-model="f.value" placeholder="选项用逗号分隔" required aria-label="口味选项"><button type="button" @click="form.flavors.splice(i,1)">移除</button></div><button type="button" @click="form.flavors.push({name:'',value:''})">＋ 添加口味</button></template><template v-if="kind==='setmeal'"><h3>套餐菜品</h3><div class="actions"><select v-model="selected" aria-label="套餐菜品"><option value="">选择菜品</option><option v-for="d in dishes" :key="d.id" :value="d.id">{{d.name}}</option></select><button type="button" @click="addDish">添加</button></div><div v-for="(d,i) in form.setmealDishes" :key="d.dishId" class="line"><span>{{d.name}}</span><input type="number" v-model.number="d.copies" min="1" max="99" required aria-label="份数"><button type="button" @click="form.setmealDishes.splice(i,1)">移除</button></div></template><button class="primary wide" :disabled="busy||uploading">{{busy?'保存中…':'保存'}}</button></form></div></template>
